#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string lineInput;
    getline(cin, lineInput);
    vector<char> sChars(lineInput.begin(), lineInput.end());
    bool foundX = false;
    int length = sChars.size();

    for (int i = 0; i < length; i++) {
        if (sChars[i] == 'X') {
            foundX = true;
        }
    }

    int totalCount = 0;
    vector<char> tempChars(length);
    for (int digit = 0; digit < 10; digit++) {
        for (int i = 0; i < length; i++) {
            if (sChars[i] == 'X') {
                tempChars[i] = '0' + digit;
            } else {
                tempChars[i] = sChars[i];
            }
        }
        if (tempChars[0] == '0') continue;

        vector<vector<int>> dpArray(2, vector<int>(25, 0));
        int currentIdx = 1;
        dpArray[0][0] = 1;

        for (int i = 0; i < length; i++) {
            fill(dpArray[currentIdx].begin(), dpArray[currentIdx].end(), 0);
            int lowBound = 0, highBound = 9, nextVal;
            if (tempChars[i] != '_') {
                lowBound = highBound = tempChars[i] - '0';
            } else if (i == 0) {
                lowBound++;
            }

            for (int prevMod = 0; prevMod < 25; prevMod++) {
                for (int digitVal = lowBound; digitVal <= highBound; digitVal++) {
                    nextVal = (prevMod * 10 + digitVal) % 25;
                    dpArray[currentIdx][nextVal] += dpArray[currentIdx ^ 1][prevMod];
                }
            }
            currentIdx ^= 1;
        }
        totalCount += dpArray[currentIdx ^ 1][0];
        if (!foundX) break;
    }

    if (length == 1 && (sChars[0] == '_' || sChars[0] == 'X' || sChars[0] == '0')) totalCount++;
    cout << totalCount << "\n";

    return 0;
}
